// The flight and aim model.
//
// Re-derived from `pewpew/docs/FLIGHT_AND_AIM.md` rather than ported from
// `railRun.js`'s `applyShipTransform`. The order of operations below matches that
// document section by section, because the order is load-bearing: carrying aim
// through the rail's rotation BEFORE applying input is what makes hands-off track a
// curving rail, and transporting the up-vector AFTER the heading settles is what
// keeps the pole continuous.
//
// Two deliberate differences from the original:
//
//   - Input is interpreted against the ship's OWN view basis, which is simulation
//     state, instead of `camera.matrixWorld`. Same feel, deterministic, and it works
//     for six ships that each have their own camera.
//   - The rail supplies a rotation-minimizing frame, so the travel box's axes come
//     from the rail rather than being rebuilt from world-up each tick.

import { clamp, expEase, Quat, tv3, Vec3 } from "@core/math/index.js";
import { idleInputFrame, pressedThisTick, type InputFrame } from "@core/input.js";
import {
  AIM_RATE,
  BOX_MOVE,
  CATCH_K,
  CONE_ANGLE,
  FWD_CONE,
  HEAD_FWD_K,
  OMNI_CONE,
  POLE_GUARD,
  RET_K,
  ROLL_LEVEL_K,
} from "@content/tuning/flight.js";
import { Button } from "../buttons.js";
import { AIM_MODES, type AimMode } from "../flight.js";
import type { MutableRailFrame } from "../rail.js";
import type { SimWorld } from "../world.js";
import type { TickInputs } from "../step.js";

const WORLD_UP = new Vec3(0, 1, 0);
/** Below this, a stick reads as centred. Quantized input never lands on exact zero. */
const DEADZONE = 1e-3;

// Scratch. Allocation-free: this runs for every ship, every tick.
const frame: MutableRailFrame = {
  position: new Vec3(),
  tangent: new Vec3(),
  normal: new Vec3(),
  binormal: new Vec3(),
};
const previousTangent = new Vec3();
const aim = new Vec3();
const head = new Vec3();
const shipUp = new Vec3();
const previousHead = new Vec3();
const basisRight = new Vec3();
const basisUp = new Vec3();
const axis = new Vec3();
const levelTarget = new Vec3();
// NOT from the tv3() ring: this one is computed before the per-ship loop and read
// inside it, and the loop itself takes ring slots. At six ships that is 12 of 64, so
// the ring would survive today — but the failure mode when it stops surviving is
// silent, because the `lengthSq() > 0.5` guard still passes on a normalized
// replacement and every ship's aim would be rotated about a wrong axis.
const carryAxis = new Vec3();
const orientation = new Quat();

/** Rotates unit `current` toward unit `target` by an exponentially eased step. */
function slerpToward(current: Vec3, target: Vec3, factor: number): void {
  const angle = Math.acos(clamp(current.dot(target), -1, 1));
  if (angle < 1e-4) {
    current.copy(target);
    return;
  }
  axis.crossVectors(current, target);
  if (axis.lengthSq() < 1e-9) {
    // Antiparallel: the rotation axis is undefined, so any perpendicular will do.
    axis.crossVectors(current, WORLD_UP);
    if (axis.lengthSq() < 1e-9) axis.set(1, 0, 0);
  }
  axis.normalize();
  current.applyAxisAngle(axis, angle * factor).normalize();
}

/** Clamps unit `dir` to within `maxAngle` of unit `coneAxis`. */
function clampCone(dir: Vec3, coneAxis: Vec3, maxAngle: number): void {
  const angle = Math.acos(clamp(dir.dot(coneAxis), -1, 1));
  if (angle <= maxAngle) return;
  axis.crossVectors(coneAxis, dir);
  if (axis.lengthSq() < 1e-9) return; // exactly antiparallel; nothing to rotate about
  axis.normalize();
  dir.copy(coneAxis).applyAxisAngle(axis, maxAngle).normalize();
}

const coneFor = (mode: AimMode): number =>
  mode === "omni" ? OMNI_CONE : mode === "forward" ? FWD_CONE : CONE_ANGLE;

export function flightSystem(world: SimWorld, inputs: TickInputs): void {
  const rail = world.rail;
  if (!rail) return;

  const course = rail.courses[world.courseId];
  if (!course) return;

  const { transform, boxOffset, aim: aimStore, viewState } = world.components;
  const dt = world.dt;

  // Constant at a fixed timestep, so they are hoisted out of the per-ship loop —
  // the payoff of `dt` being a constant rather than a frame delta.
  const catchFactor = expEase(CATCH_K, dt);
  const recenterFactor = expEase(RET_K, dt);
  const levelFactor = expEase(HEAD_FWD_K, dt);
  const rollFactor = expEase(ROLL_LEVEL_K, dt);
  const boxStep = BOX_MOVE * dt;
  const turnStep = AIM_RATE * dt;

  // ── 1. Advance the rail, and note the rotation its tangent underwent ─────────
  // Both tangents are derived from arc lengths we already know, so no previous-frame
  // state has to be stored — which keeps the snapshot smaller and rewind-safe.
  course.tangentAt(world.railS, previousTangent);
  if (!world.railHolding && world.outcome === "running") {
    world.railS = Math.min(course.length, world.railS + world.railSpeed * dt);
  }
  course.frameAt(world.railS, frame);

  const carryAngle = Math.acos(clamp(previousTangent.dot(frame.tangent), -1, 1));
  const hasCarry = carryAngle > 1e-5;
  carryAxis.set(0, 0, 0);
  if (hasCarry) {
    carryAxis.crossVectors(previousTangent, frame.tangent);
    if (carryAxis.lengthSq() > 1e-9) carryAxis.normalize();
  }

  const boxHalfWidth = course.box.width / 2;
  const boxHalfHeight = course.box.height / 2;

  // Iterate by SLOT rather than dense row: both are deterministic, but slot order
  // stays stable across joins and leaves.
  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const t = transform.row(entity);
    const b = boxOffset.row(entity);
    const a = aimStore.row(entity);
    const v = viewState.row(entity);
    if (t < 0 || b < 0 || a < 0 || v < 0) continue;

    const input: InputFrame = inputs[slot] ?? idleInputFrame(world.tick);

    // ── 2. Modes ──────────────────────────────────────────────────────────────
    // A stop overrides the player's toggle while parked (step 4 sets `forcedAimMode`).
    let mode: AimMode = AIM_MODES[viewState.columns.aimMode[v]!] ?? "free";
    const pressed = pressedThisTick(
      { tick: world.tick, steerX: 0, steerY: 0, buttons: viewState.columns.lastButtons[v]! },
      input,
    );
    if (pressed & Button.AimMode) {
      mode = mode === "forward" ? "free" : "forward";
      viewState.columns.aimMode[v] = AIM_MODES.indexOf(mode);
    }
    if (pressed & Button.ViewToggle) {
      const next = viewState.columns.viewMode[v] === 0 ? 1 : 0;
      viewState.columns.viewMode[v] = next;
    }
    viewState.columns.lastButtons[v] = input.buttons;

    if (world.forcedAimMode) mode = world.forcedAimMode;
    const omni = mode === "omni";
    const cone = coneFor(mode);

    aim.readFrom(aimStore.columns.aimDir, a * 3);
    head.readFrom(aimStore.columns.headDir, a * 3);
    shipUp.readFrom(aimStore.columns.shipUp, a * 3);
    previousHead.copy(head);

    // ── 3. Carry aim and heading through the rail's rotation ──────────────────
    // Without this, "hands off" would lag a curving rail instead of tracking it.
    if (hasCarry && carryAxis.lengthSq() > 0.5) {
      aim.applyAxisAngle(carryAxis, carryAngle);
      head.applyAxisAngle(carryAxis, carryAngle);
      shipUp.applyAxisAngle(carryAxis, carryAngle);
    }

    // ── 4. The travel box ─────────────────────────────────────────────────────
    // On the track and at a forward stop, steering BOTH slides and turns. In omni
    // the heading can point anywhere, so the box axes and the view axes disagree —
    // there, steering turns only.
    const steerX = Math.abs(input.steerX) > DEADZONE ? input.steerX : 0;
    const steerY = Math.abs(input.steerY) > DEADZONE ? input.steerY : 0;
    const steering = steerX !== 0 || steerY !== 0;

    if (!omni) {
      const ox = clamp(boxOffset.columns.ox[b]! + steerX * boxStep, -boxHalfWidth, boxHalfWidth);
      const oy = clamp(boxOffset.columns.oy[b]! + steerY * boxStep, -boxHalfHeight, boxHalfHeight);
      boxOffset.columns.ox[b] = ox;
      boxOffset.columns.oy[b] = oy;
    }

    // ── 5. Aim: the reticle leads, the heading lags ───────────────────────────
    // View-relative, against the ship's own basis rather than a render camera.
    basisUp.copy(shipUp).orthogonalize(head);
    if (basisUp.lengthSq() < 1e-12) basisUp.copy(frame.normal).orthogonalize(head);
    basisUp.normalize();
    basisRight.crossVectors(head, basisUp).normalize();

    if (steering) {
      if (steerX !== 0) aim.applyAxisAngle(basisUp, -steerX * turnStep);
      if (steerY !== 0) aim.applyAxisAngle(basisRight, steerY * turnStep);
      aim.normalize();
      clampCone(aim, frame.tangent, cone);
    } else {
      slerpToward(aim, head, recenterFactor);
    }

    slerpToward(head, aim, catchFactor);
    clampCone(head, frame.tangent, cone);

    // Auto-level to forward when hands off, so a held bank turns fully and letting
    // go returns to down-track flight. Omni is the one mode without it: there you
    // keep whatever heading you point, which is the point of turning around.
    if (!omni && !steering) slerpToward(head, frame.tangent, levelFactor);

    // ── 6. Ship up: parallel transport, not a rebuild ─────────────────────────
    const headingChange = Math.acos(clamp(previousHead.dot(head), -1, 1));
    if (headingChange > 1e-6) {
      axis.crossVectors(previousHead, head);
      if (axis.lengthSq() > 1e-9) {
        axis.normalize();
        shipUp.applyAxisAngle(axis, headingChange);
      }
    }

    // Re-level the wings toward world-up, but only hands-off and away from the
    // vertical pole. The re-level target reverses sign across the pole, so applying
    // it there would reintroduce exactly the discontinuity transport exists to avoid.
    levelTarget.copy(WORLD_UP).orthogonalize(head);
    if (!steering && levelTarget.lengthSq() > POLE_GUARD) {
      levelTarget.normalize();
      slerpToward(shipUp, levelTarget, rollFactor);
    }

    shipUp.orthogonalize(head);
    if (shipUp.lengthSq() < 1e-6) shipUp.copy(frame.normal).orthogonalize(head);
    shipUp.normalize();

    // ── 7. Write back ─────────────────────────────────────────────────────────
    aim.writeTo(aimStore.columns.aimDir, a * 3);
    head.writeTo(aimStore.columns.headDir, a * 3);
    shipUp.writeTo(aimStore.columns.shipUp, a * 3);

    // Position: the rail centre plus the box offset, on the rail's own axes.
    const position = tv3()
      .copy(frame.position)
      .addScaledVector(frame.binormal, boxOffset.columns.ox[b]!)
      .addScaledVector(frame.normal, boxOffset.columns.oy[b]!);
    position.writeTo(transform.columns.pos, t * 3);

    // Orientation: nose (+X) along the heading, wings (+Y) along the transported up.
    const zAxis = tv3().crossVectors(head, shipUp).normalize();
    orientation.setFromBasis(head, shipUp, zAxis).writeTo(transform.columns.rot, t * 4);
  }
}
