// Collision.
//
// Runs AFTER motion, and tests projectiles as SWEPT SEGMENTS rather than points. At
// 120 units/second a bolt covers two units per tick while a hazard is 1.5 across, so
// a point test would let shots tunnel straight through — intermittently, depending on
// where the tick boundary happened to fall, which is the worst kind of bug to chase.
//
// The broadphase is a naive double loop. At M1a scale (a few hundred projectiles
// against a few dozen hazards) that is comfortably cheap, and a spatial index is an
// M2 concern once enemy counts grow. Written as an explicit loop rather than hidden
// behind a helper so the cost is visible when that day comes.

import { clamp, Vec3 } from "@core/math/index.js";
import type { Entity } from "@core/ecs.js";
import type { SimWorld } from "../world.js";

/** Ship collision radius. Becomes a per-hull stat in M2. */
const SHIP_RADIUS = 1;
/** Damage a ship takes from ramming a hazard. */
const RAM_DAMAGE = 25;

const hazardPos = new Vec3();
const shotPos = new Vec3();
const shotStart = new Vec3();
const segment = new Vec3();
const toHazard = new Vec3();
const shipPos = new Vec3();

/** Squared distance from `point` to the segment `start → end`. */
function distanceSqToSegment(point: Vec3, start: Vec3, end: Vec3): number {
  segment.copy(end).sub(start);
  const lengthSq = segment.lengthSq();
  toHazard.copy(point).sub(start);
  if (lengthSq < 1e-12) return toHazard.lengthSq();

  const t = clamp(toHazard.dot(segment) / lengthSq, 0, 1);
  return toHazard.addScaledVector(segment, -t).lengthSq();
}

export function collisionSystem(world: SimWorld): void {
  const { transform, motion, projectile, hazard, ship } = world.components;
  const dt = world.dt;

  // ── Projectiles against hazards ─────────────────────────────────────────────
  // Iterate backwards: a hit queues destruction, and while that is deferred, the
  // reverse walk keeps the loop correct even if that ever changes.
  for (let p = projectile.count - 1; p >= 0; p--) {
    const shot = projectile.dense[p]! as Entity;
    const t = transform.row(shot);
    const m = motion.row(shot);
    if (t < 0 || m < 0) continue;

    shotPos.readFrom(transform.columns.pos, t * 3);
    shotStart
      .readFrom(motion.columns.vel, m * 3)
      .multiplyScalar(-dt)
      .add(shotPos); // where it was at the start of this tick

    for (let h = hazard.count - 1; h >= 0; h--) {
      const target = hazard.dense[h]! as Entity;
      const ht = transform.row(target);
      if (ht < 0) continue;

      hazardPos.readFrom(transform.columns.pos, ht * 3);
      const radius = hazard.columns.radius[h]!;
      if (distanceSqToSegment(hazardPos, shotStart, shotPos) > radius * radius) continue;

      const damage = projectile.columns.damage[p]!;
      const remaining = hazard.columns.health[h]! - damage;
      hazard.columns.health[h] = remaining;

      // The projectile is spent whether or not the hazard died — otherwise one bolt
      // would rake a whole cluster, which is not what "fire a shot" means.
      world.ecs.destroyLater(shot);
      if (remaining <= 0) world.destroyHazard(target, projectile.columns.ownerSlot[p]!);
      break;
    }
  }

  // ── Hazards against ships ───────────────────────────────────────────────────
  // By slot, not by dense row: both are deterministic, but slot order stays stable
  // as players join and leave, so a six-player run resolves the same way every time.
  for (let slot = 0; slot < world.shipBySlot.length; slot++) {
    const entity = world.shipBySlot[slot];
    if (entity === undefined || !world.ecs.isAlive(entity)) continue;

    const s = ship.row(entity);
    const t = transform.row(entity);
    if (s < 0 || t < 0 || ship.columns.health[s]! <= 0) continue;

    shipPos.readFrom(transform.columns.pos, t * 3);

    for (let h = hazard.count - 1; h >= 0; h--) {
      const target = hazard.dense[h]! as Entity;
      const ht = transform.row(target);
      if (ht < 0) continue;

      hazardPos.readFrom(transform.columns.pos, ht * 3);
      const reach = hazard.columns.radius[h]! + SHIP_RADIUS;
      if (hazardPos.distanceToSq(shipPos) > reach * reach) continue;

      world.damageShip(entity, RAM_DAMAGE);
      // The hazard is consumed, so a single rock cannot grind a ship down over
      // consecutive ticks while the two overlap.
      world.destroyHazard(target, -1);
    }
  }
}
