// The rail — precomputed, immutable geometry.
//
// Three deliberate departures from the old `railShooter.js`:
//
// 1. ARC-LENGTH PARAMETERIZED. The old follower advanced by a per-segment `duration`
//    in milliseconds (`railShooter.js:151`), so a segment's effective speed depended
//    on how far apart its waypoints happened to be — an authoring trap that misleads
//    every time someone drags a waypoint. Here position is a function of distance
//    travelled, and speed is world units per second.
//
// 2. CENTRIPETAL Catmull-Rom tangents. The old uniform formula
//    (`railShooter.js:30`, tangent = (next - prev) * 0.5) overshoots when waypoints
//    are unevenly spaced. On a collinear rail with 5-, 100-, and 5-unit segments it
//    drives the curve backward to x = -4.08 before coming forward — the rail loops
//    past its own start. Centripetal parameterization (knots spaced by chord^0.5)
//    provably admits no cusps or self-intersections within a segment.
//
// 3. ROTATION-MINIMIZING FRAMES. The old model rebuilt a basis from world-up each
//    frame, which degenerates when the heading points straight up or down, and
//    papered over it with a `POLE_GUARD`. An RMF (double-reflection method) is
//    continuous by construction, so the pole stops being a special case.
//
// The payoff for multiplayer: every rail quantity is a pure function of one scalar
// `s`, so co-op position sync is `s` plus each ship's box offset — around 13 floats
// for a full party.

import { Vec3, tv3 } from "@core/math/index.js";
import { DEFAULT_BOX_HEIGHT, DEFAULT_BOX_WIDTH } from "@content/tuning/flight.js";
import type {
  BranchSelector,
  RailBranch,
  RailSpec,
  RailWaypoint,
} from "@content/schemas/level.js";

// The authored shapes live in `content`; the built ones (`Rail`, `RailNetwork`, `Fork`)
// are this module's own. Re-exported so a caller that builds a rail from a spec does
// not have to import from two layers to do it.
export type { BranchSelector, RailBranch, RailSpec, RailWaypoint };

/** An orthonormal, right-handed frame riding the rail. */
export interface RailFrame {
  /** Point on the rail. */
  readonly position: Vec3;
  /** Unit direction of travel. */
  readonly tangent: Vec3;
  /** Frame "up" — rotation-minimizing, NOT rebuilt from world-up. */
  readonly normal: Vec3;
  /** tangent × normal. The travel box's width axis. */
  readonly binormal: Vec3;
}

export interface RailOptions {
  /**
   * Minimum arc-length samples per segment. Sampling is adaptive on top of this —
   * see `targetSampleSpacing`. Costs build time only; nothing here runs per tick.
   */
  readonly samplesPerSegment?: number;
  /**
   * Target world-unit spacing between arc-length samples.
   *
   * Sampling every segment equally would give a 100-unit segment the same resolution
   * as a 5-unit one, and the table intervals on the long segment would then be
   * coarser than a typical query step — which shows up directly as non-uniform
   * speed, the very thing arc-length parameterization exists to fix.
   */
  readonly targetSampleSpacing?: number;
  /** Travel box cross-section. Falls back to the content defaults. */
  readonly box?: { readonly width: number; readonly height: number } | undefined;
}

export interface Rail {
  /** Total arc length in world units. */
  readonly length: number;
  readonly waypointCount: number;
  readonly box: { readonly width: number; readonly height: number };

  waypointAt(index: number): RailWaypoint;
  /** Arc-length distance from the start to waypoint `index`. */
  distanceAtWaypoint(index: number): number;
  /** Index of the first waypoint strictly after arc-length `s`, or -1 past the end. */
  nextWaypointAfter(s: number): number;

  /** Position at arc-length `s`, clamped to `[0, length]`. Writes and returns `out`. */
  sample(s: number, out: Vec3): Vec3;
  /** Unit travel direction at `s`. Writes and returns `out`. */
  tangentAt(s: number, out: Vec3): Vec3;
  /** The full rotation-minimizing frame at `s`. Writes and returns `out`. */
  frameAt(s: number, out: MutableRailFrame): RailFrame;
}

/** A `RailFrame` whose vectors the caller owns and may have written into. */
export interface MutableRailFrame {
  position: Vec3;
  tangent: Vec3;
  normal: Vec3;
  binormal: Vec3;
}

const DEFAULT_SAMPLES_PER_SEGMENT = 32;
const DEFAULT_SAMPLE_SPACING = 0.25;
const EPS = 1e-9;

// ── Hermite basis ─────────────────────────────────────────────────────────────

const h00 = (t: number): number => 2 * t * t * t - 3 * t * t + 1;
const h10 = (t: number): number => t * t * t - 2 * t * t + t;
const h01 = (t: number): number => -2 * t * t * t + 3 * t * t;
const h11 = (t: number): number => t * t * t - t * t;

// Derivatives, for the analytic tangent.
const d00 = (t: number): number => 6 * t * t - 6 * t;
const d10 = (t: number): number => 3 * t * t - 4 * t + 1;
const d01 = (t: number): number => -6 * t * t + 6 * t;
const d11 = (t: number): number => 3 * t * t - 2 * t;

/**
 * Builds the immutable rail from authored waypoints.
 *
 * Precomputes the arc-length table and the rotation-minimizing frames once, at level
 * load. Nothing here runs per tick.
 */
export function buildRail(waypoints: readonly RailWaypoint[], options: RailOptions = {}): Rail {
  if (waypoints.length < 2) {
    throw new Error(`buildRail: a rail needs at least 2 waypoints, got ${waypoints.length}`);
  }

  const {
    samplesPerSegment = DEFAULT_SAMPLES_PER_SEGMENT,
    targetSampleSpacing = DEFAULT_SAMPLE_SPACING,
    box,
  } = options;

  const count = waypoints.length;
  const segments = count - 1;

  const points = waypoints.map((w) => Vec3.from(w.position));

  // ── Centripetal Catmull-Rom knots ───────────────────────────────────────────
  // Knot i+1 sits chord^0.5 beyond knot i. This is what prevents the overshoot the
  // uniform formula produces on unevenly spaced waypoints.
  const knots = new Float64Array(count);
  for (let i = 1; i < count; i++) {
    const chord = points[i]!.distanceTo(points[i - 1]!);
    // A duplicated waypoint would give a zero knot span and divide by zero below.
    knots[i] = knots[i - 1]! + Math.max(Math.sqrt(chord), EPS);
  }

  /**
   * Global derivative dP/dknot at waypoint `i`, one-sided at the ends.
   * A `lookAt` handle replaces the DIRECTION but keeps the automatic magnitude.
   */
  const gradientAt = (i: number, out: Vec3): Vec3 => {
    if (i <= 0) {
      out.subVectors(points[1]!, points[0]!).multiplyScalar(1 / (knots[1]! - knots[0]!));
    } else if (i >= count - 1) {
      out
        .subVectors(points[count - 1]!, points[count - 2]!)
        .multiplyScalar(1 / (knots[count - 1]! - knots[count - 2]!));
    } else {
      out
        .subVectors(points[i + 1]!, points[i - 1]!)
        .multiplyScalar(1 / (knots[i + 1]! - knots[i - 1]!));
    }

    const look = waypoints[i]!.lookAt;
    if (look) {
      const magnitude = out.length();
      const direction = tv3(look[0] - points[i]!.x, look[1] - points[i]!.y, look[2] - points[i]!.z);
      if (direction.lengthSq() > EPS) out.copy(direction).normalize().multiplyScalar(magnitude);
    }
    return out;
  };

  const gradients = points.map((_, i) => gradientAt(i, new Vec3()));

  // ── Spline evaluation in the global parameter u ∈ [0, segments] ─────────────
  // The integer part selects a segment, the fraction is the Hermite parameter.

  const evaluate = (u: number, out: Vec3): Vec3 => {
    const seg = Math.min(segments - 1, Math.max(0, Math.floor(u)));
    const t = Math.min(1, Math.max(0, u - seg));
    const span = knots[seg + 1]! - knots[seg]!;

    const p0 = points[seg]!;
    const p1 = points[seg + 1]!;
    const m0 = gradients[seg]!;
    const m1 = gradients[seg + 1]!;

    return out
      .set(0, 0, 0)
      .addScaledVector(p0, h00(t))
      .addScaledVector(m0, h10(t) * span)
      .addScaledVector(p1, h01(t))
      .addScaledVector(m1, h11(t) * span);
  };

  const derivative = (u: number, out: Vec3): Vec3 => {
    const seg = Math.min(segments - 1, Math.max(0, Math.floor(u)));
    const t = Math.min(1, Math.max(0, u - seg));
    const span = knots[seg + 1]! - knots[seg]!;

    out
      .set(0, 0, 0)
      .addScaledVector(points[seg]!, d00(t))
      .addScaledVector(gradients[seg]!, d10(t) * span)
      .addScaledVector(points[seg + 1]!, d01(t))
      .addScaledVector(gradients[seg + 1]!, d11(t) * span);

    // A degenerate derivative (coincident waypoints) would normalize to zero; fall
    // back to the segment chord so the travel direction stays meaningful.
    if (out.lengthSq() < EPS) out.subVectors(points[seg + 1]!, points[seg]!);
    return out.normalize();
  };

  // ── Adaptive arc-length table ───────────────────────────────────────────────
  // Sample count per segment scales with its chord, so a long segment is not left
  // coarser than a typical query step.

  const perSegment: number[] = [];
  let totalSamples = 1; // the shared start point
  for (let seg = 0; seg < segments; seg++) {
    const chord = points[seg + 1]!.distanceTo(points[seg]!);
    const n = Math.max(samplesPerSegment, Math.ceil(chord / targetSampleSpacing));
    perSegment.push(n);
    totalSamples += n;
  }

  const sampleU = new Float64Array(totalSamples);
  const sampleS = new Float64Array(totalSamples);
  const samplePos = new Float64Array(totalSamples * 3);
  const sampleTan = new Float64Array(totalSamples * 3);
  const sampleNormal = new Float64Array(totalSamples * 3);
  /** Arc length at each waypoint — index into the table at segment boundaries. */
  const waypointS = new Float64Array(count);

  const scratch = new Vec3();
  let write = 0;
  let accumulated = 0;

  const putSample = (u: number, s: number): void => {
    sampleU[write] = u;
    sampleS[write] = s;
    evaluate(u, scratch).writeTo(samplePos, write * 3);
    derivative(u, scratch).writeTo(sampleTan, write * 3);
    write++;
  };

  putSample(0, 0);
  const previous = new Vec3().readFrom(samplePos, 0);
  const current = new Vec3();

  for (let seg = 0; seg < segments; seg++) {
    const n = perSegment[seg]!;
    for (let k = 1; k <= n; k++) {
      const u = seg + k / n;
      evaluate(u, current);
      accumulated += current.distanceTo(previous);
      putSample(u, accumulated);
      previous.copy(current);
    }
    waypointS[seg + 1] = accumulated;
  }

  const length = accumulated;

  // ── Rotation-minimizing frames, by double reflection ────────────────────────
  // Wang et al. 2008. Each frame is carried to the next sample by two reflections,
  // which is what makes the sequence continuous even where the curve passes through
  // vertical — the case a world-up-derived basis flips on.

  const seedNormal = (out: Vec3): Vec3 => {
    const t0 = tv3().readFrom(sampleTan, 0);
    // Project world-up perpendicular to the tangent. If the rail starts vertical,
    // world-up is parallel to it and the projection degenerates — fall back to +X.
    out.set(0, 1, 0).orthogonalize(t0);
    if (out.lengthSq() < 1e-6) out.set(1, 0, 0).orthogonalize(t0);
    if (out.lengthSq() < 1e-6) out.set(0, 0, 1).orthogonalize(t0);
    return out.normalize();
  };

  {
    const r = seedNormal(new Vec3());
    r.writeTo(sampleNormal, 0);

    const x0 = new Vec3();
    const x1 = new Vec3();
    const t0 = new Vec3();
    const t1 = new Vec3();
    const v1 = new Vec3();
    const v2 = new Vec3();
    const rL = new Vec3();
    const tL = new Vec3();

    for (let i = 0; i + 1 < totalSamples; i++) {
      x0.readFrom(samplePos, i * 3);
      x1.readFrom(samplePos, (i + 1) * 3);
      t0.readFrom(sampleTan, i * 3);
      t1.readFrom(sampleTan, (i + 1) * 3);

      // First reflection: across the plane bisecting the two sample points.
      v1.subVectors(x1, x0);
      const c1 = v1.lengthSq();
      if (c1 > EPS) {
        rL.copy(r).addScaledVector(v1, (-2 / c1) * v1.dot(r));
        tL.copy(t0).addScaledVector(v1, (-2 / c1) * v1.dot(t0));
      } else {
        rL.copy(r);
        tL.copy(t0);
      }

      // Second reflection: brings the transported tangent onto the next tangent.
      v2.subVectors(t1, tL);
      const c2 = v2.lengthSq();
      if (c2 > EPS) {
        r.copy(rL).addScaledVector(v2, (-2 / c2) * v2.dot(rL));
      } else {
        r.copy(rL);
      }

      // Re-orthogonalize against drift, then store.
      r.orthogonalize(t1);
      if (r.lengthSq() < 1e-12) r.copy(seedNormal(tv3()));
      r.normalize().writeTo(sampleNormal, (i + 1) * 3);
    }
  }

  // ── Queries ─────────────────────────────────────────────────────────────────

  const clampS = (s: number): number =>
    !Number.isFinite(s) ? 0 : s < 0 ? 0 : s > length ? length : s;

  /** Largest table index whose `s` is <= the target. Binary search. */
  const indexForS = (s: number): number => {
    let lo = 0;
    let hi = totalSamples - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (sampleS[mid]! <= s) lo = mid;
      else hi = mid - 1;
    }
    return Math.min(lo, totalSamples - 2);
  };

  /** Fraction between table entries `i` and `i+1` for arc length `s`. */
  const fractionAt = (i: number, s: number): number => {
    const s0 = sampleS[i]!;
    const span = sampleS[i + 1]! - s0;
    return span <= EPS ? 0 : Math.min(1, Math.max(0, (s - s0) / span));
  };

  /**
   * The global spline parameter at arc length `s`.
   *
   * Interpolating `u` and re-evaluating the spline keeps the curve genuinely curved.
   * Interpolating between the stored POSITIONS instead would be marginally cheaper
   * and would quietly turn the rail into a polyline.
   */
  const uForS = (s: number): number => {
    const i = indexForS(s);
    const f = fractionAt(i, s);
    return sampleU[i]! + (sampleU[i + 1]! - sampleU[i]!) * f;
  };

  const rail: Rail = {
    length,
    waypointCount: count,
    box: box ?? { width: DEFAULT_BOX_WIDTH, height: DEFAULT_BOX_HEIGHT },

    waypointAt(index) {
      const w = waypoints[index];
      if (!w) throw new RangeError(`waypointAt: index ${index} out of range 0..${count - 1}`);
      return w;
    },

    distanceAtWaypoint(index) {
      if (index < 0 || index >= count) {
        throw new RangeError(`distanceAtWaypoint: index ${index} out of range 0..${count - 1}`);
      }
      return waypointS[index]!;
    },

    nextWaypointAfter(s) {
      for (let i = 0; i < count; i++) if (waypointS[i]! > s) return i;
      return -1;
    },

    sample(s, out) {
      return evaluate(uForS(clampS(s)), out);
    },

    tangentAt(s, out) {
      return derivative(uForS(clampS(s)), out);
    },

    frameAt(s, out) {
      const clamped = clampS(s);
      const i = indexForS(clamped);
      const f = fractionAt(i, clamped);

      evaluate(uForS(clamped), out.position);
      derivative(uForS(clamped), out.tangent);

      // Interpolate the stored normals rather than re-propagating. This is what
      // makes `frameAt` a pure lookup: the frame at a given `s` does not depend on
      // which `s` values were queried before it.
      out.normal.readFrom(sampleNormal, i * 3);
      const next = tv3().readFrom(sampleNormal, (i + 1) * 3);
      out.normal.lerp(next, f);

      out.normal.orthogonalize(out.tangent);
      if (out.normal.lengthSq() < 1e-12) {
        out.normal.set(0, 1, 0).orthogonalize(out.tangent);
        if (out.normal.lengthSq() < 1e-12) out.normal.set(1, 0, 0).orthogonalize(out.tangent);
      }
      out.normal.normalize();
      out.binormal.crossVectors(out.tangent, out.normal).normalize();
      return out;
    },
  };

  return rail;
}

// ─────────────────────────────────────────────────────────────────────────────
// Branches
// ─────────────────────────────────────────────────────────────────────────────
//
// A branching rail is stored as a tree — a trunk plus branches that fork off a
// parent's waypoint — and FLATTENED at build time into one complete `Rail` per
// root-to-leaf course, which is what the old `flattenCourse` in `worlds.js` did.
// Every rail quantity therefore stays a pure function of `(courseId, s)`, and the
// entire party's rail state is `{ courseId: u8, s: f32 }` — five bytes. The host
// picks at a fork and replicates one integer; everyone else follows.
//
// THE COMMIT RULE, which is the whole subtlety here:
//
// You cannot decide the branch AT the fork. A centripetal Catmull-Rom tangent at
// waypoint F depends on the waypoint after F — which is course-specific — so the
// courses have already parted before they formally split. Measured on a collinear
// trunk forking to ±Z:
//
//     segment [F-2 → F-1]:  divergence = 0.0000 world units
//     segment [F-1 → F  ]:  divergence = 2.9079 world units   (~half a box width)
//
// So the choice commits one full segment early, at `distanceAtWaypoint(F - 1)`,
// where the geometry is still identical across every course through the fork.
// Switching there is seamless; switching at F would visibly jerk the ship sideways.
// It is also the better game feel: the rail bends toward the chosen path before the
// split, telegraphing it.

const PARTY_LATERAL: BranchSelector = { kind: "partyLateral" };

export interface ForkOption {
  /**
   * The course to switch to. Where an option itself forks further downstream, this
   * is its lowest-numbered course; that option's own fork resolves the rest later.
   */
  readonly courseId: number;
  /**
   * Signed offset of this option along the fork frame's binormal — negative is left,
   * positive is right. Derived from geometry, so authors never maintain a "side".
   */
  readonly lateral: number;
}

export interface Fork {
  readonly key: string;
  /**
   * Arc length at which the choice locks in — one full segment before the fork.
   * Identical on every course through this fork, which is what makes switching here
   * free. This is the only arc length the runtime should use.
   */
  readonly commitS: number;
  /**
   * Flattened waypoint index of the fork itself. Same on every course through it —
   * but the arc length to REACH it is not: a course whose approach segment bends
   * toward its branch travels further. Measured on the reference fixture, the trunk
   * reaches the fork waypoint at s=100.000 while both branches reach it at
   * s=100.311. Use `courses[id].distanceAtWaypoint(forkWaypointIndex)` if you need a
   * course's own value, and never treat it as shared.
   */
  readonly forkWaypointIndex: number;
  readonly options: readonly ForkOption[];
  readonly selector: BranchSelector;
}

export interface SelectionContext {
  /** Mean box offset of the party along the box width axis, in world units. */
  readonly partyLateral: number;
  readonly boxHalfWidth: number;
  /** Triggers fired so far this run. */
  readonly firedTriggers?: ReadonlySet<string> | undefined;
}

export interface RailNetwork {
  /** One complete rail per root-to-leaf course. Course 0 is always the trunk. */
  readonly courses: readonly Rail[];
  readonly courseCount: number;
  readonly box: { readonly width: number; readonly height: number };
  /** Forks a course passes through, ascending by `commitS`. */
  forksOn(courseId: number): readonly Fork[];
  /** The first fork on `courseId` whose commit point is at or after `s`, else null. */
  nextForkOn(courseId: number, s: number): Fork | null;
}

const forkKey = (parent: string | null, atWaypoint: number): string =>
  `${parent ?? "trunk"}:${atWaypoint}`;

/**
 * Chooses which course a fork leads to. Pure — it reads no world state, so the host
 * can evaluate it and replicate the single resulting integer.
 */
export function chooseCourse(fork: Fork, ctx: SelectionContext): number {
  const options = fork.options;
  if (options.length === 0) throw new Error(`chooseCourse: fork ${fork.key} has no options`);
  if (options.length === 1) return options[0]!.courseId;

  if (fork.selector.kind === "trigger") {
    const { triggerId, defaultOption } = fork.selector;
    const fired = ctx.firedTriggers?.has(triggerId) ?? false;
    const index = fired ? defaultOption : findDefaultFallback(options, defaultOption);
    return options[Math.min(Math.max(index, 0), options.length - 1)]!.courseId;
  }

  // partyLateral: normalize both sides onto [-1, 1] and take the nearest option.
  // Normalizing the options by their own largest magnitude means the rule does not
  // care how far apart the branches were authored, only which way they go.
  let widest = 0;
  for (const option of options) widest = Math.max(widest, Math.abs(option.lateral));
  const party = ctx.boxHalfWidth > EPS ? ctx.partyLateral / ctx.boxHalfWidth : 0;

  let best = options[0]!;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const option of options) {
    const normalized = widest > EPS ? option.lateral / widest : 0;
    const distance = Math.abs(normalized - party);
    // Strictly-less keeps the earliest authored option on a tie, so a centred party
    // gets a stable, authored answer rather than one that depends on iteration order.
    if (distance < bestDistance - 1e-9) {
      bestDistance = distance;
      best = option;
    }
  }
  return best.courseId;
}

/** A trigger that has not fired falls back to the authored default option. */
const findDefaultFallback = (options: readonly ForkOption[], defaultOption: number): number =>
  defaultOption >= 0 && defaultOption < options.length ? defaultOption : 0;

interface CourseBuild {
  /** Flattened waypoints, root to leaf. */
  readonly waypoints: RailWaypoint[];
  /** Fork keys passed through, with the flattened index of each fork waypoint. */
  readonly forks: Array<{ key: string; forkIndex: number }>;
  /** Leaf branch id, or null for the trunk course. */
  readonly leafId: string | null;
}

/**
 * Builds every course of a branching rail, plus the fork table.
 *
 * Courses are enumerated exactly as the old `courseLeaves` did: the trunk, then every
 * leaf branch (one that nothing else forks off). Nested forks fall out for free.
 */
export function buildRailNetwork(spec: RailSpec, options: RailOptions = {}): RailNetwork {
  const branches = spec.branches ?? [];
  const byId = new Map(branches.map((b) => [b.id, b]));

  for (const branch of branches) {
    const parentId = branch.parent ?? null;
    if (parentId !== null && !byId.has(parentId)) {
      throw new Error(`buildRailNetwork: branch "${branch.id}" has unknown parent "${parentId}"`);
    }
    if (branch.waypoints.length === 0) {
      throw new Error(`buildRailNetwork: branch "${branch.id}" has no waypoints`);
    }
    // A fork at waypoint 0 has no preceding segment, so there is nowhere to commit
    // the choice before the courses have already parted.
    if (branch.atWaypoint < 1) {
      throw new Error(
        `buildRailNetwork: branch "${branch.id}" forks at waypoint ${branch.atWaypoint}; ` +
          "a fork needs at least one preceding segment so the choice can commit before " +
          "the courses diverge. Fork at waypoint 1 or later.",
      );
    }
  }

  /**
   * Walks parents to the trunk, concatenating each level's prefix up to and
   * INCLUDING its fork waypoint — the same shape as the old `flattenUpTo`.
   */
  const flattenUpTo = (branchId: string | null, upToIndex: number): CourseBuild => {
    if (branchId === null) {
      return { waypoints: spec.waypoints.slice(0, upToIndex + 1), forks: [], leafId: null };
    }
    const branch = byId.get(branchId)!;
    const parentId = branch.parent ?? null;
    const prefix = flattenUpTo(parentId, branch.atWaypoint);
    // The fork waypoint is the last of the prefix.
    const forkIndex = prefix.waypoints.length - 1;
    return {
      waypoints: prefix.waypoints.concat(branch.waypoints.slice(0, upToIndex + 1)),
      forks: [...prefix.forks, { key: forkKey(parentId, branch.atWaypoint), forkIndex }],
      leafId: branchId,
    };
  };

  const flattenCourse = (leafId: string | null): CourseBuild => {
    if (leafId === null) return { waypoints: spec.waypoints.slice(), forks: [], leafId: null };
    const branch = byId.get(leafId)!;
    const parentId = branch.parent ?? null;
    const prefix = flattenUpTo(parentId, branch.atWaypoint);
    const forkIndex = prefix.waypoints.length - 1;
    return {
      waypoints: prefix.waypoints.concat(branch.waypoints),
      forks: [...prefix.forks, { key: forkKey(parentId, branch.atWaypoint), forkIndex }],
      leafId,
    };
  };

  // Selectable courses: the trunk, plus EVERY branch's own continuation.
  //
  // Not "trunk plus leaves", which is what the old `courseLeaves` returned. If a
  // branch forks further, carrying straight on down that branch is still a path a
  // player can take, and it needs a course id for the fork to switch to. Treating
  // intermediate branches as non-destinations would silently remove that option.
  const leaves: (string | null)[] = [null, ...branches.map((b) => b.id)];

  const builds = leaves.map(flattenCourse);
  const courses = builds.map((build) => buildRail(build.waypoints, options));
  const box = courses[0]!.box;

  // ── Fork table ──────────────────────────────────────────────────────────────
  // A fork is defined by its shared PREFIX — the waypoints every course through it
  // has in common, ending at the fork waypoint. Membership is then just "does this
  // course start with that prefix", which is exact rather than heuristic: `slice`
  // and `concat` preserve object identity, so the waypoints compare by reference.

  interface ForkDef {
    readonly key: string;
    readonly prefix: readonly RailWaypoint[];
    readonly forkIndex: number;
  }

  const forkDefs = new Map<string, ForkDef>();
  for (const branch of branches) {
    const parentId = branch.parent ?? null;
    const key = forkKey(parentId, branch.atWaypoint);
    if (forkDefs.has(key)) continue; // siblings share a fork
    const prefix = flattenUpTo(parentId, branch.atWaypoint).waypoints;
    forkDefs.set(key, { key, prefix, forkIndex: prefix.length - 1 });
  }

  const startsWith = (build: CourseBuild, prefix: readonly RailWaypoint[]): boolean => {
    if (build.waypoints.length < prefix.length) return false;
    for (let i = 0; i < prefix.length; i++) if (build.waypoints[i] !== prefix[i]) return false;
    return true;
  };

  const scratchFrame: MutableRailFrame = {
    position: new Vec3(),
    tangent: new Vec3(),
    normal: new Vec3(),
    binormal: new Vec3(),
  };
  const probe = new Vec3();

  const forks: Fork[] = [];
  for (const def of forkDefs.values()) {
    const members: number[] = [];
    for (let courseId = 0; courseId < builds.length; courseId++) {
      if (startsWith(builds[courseId]!, def.prefix)) members.push(courseId);
    }
    if (members.length === 0) continue;

    // One full segment before the fork — see THE COMMIT RULE above. Every member
    // agrees on this value because they share all geometry up to it.
    const reference = courses[members[0]!]!;
    const commitS = reference.distanceAtWaypoint(def.forkIndex - 1);

    // Measure "which side" against the frame at the COMMIT point, not at the fork.
    // The frame at the fork is already rotated toward whichever branch that course
    // takes, which would bias the sides and break symmetry.
    reference.frameAt(commitS, scratchFrame);
    const forkPosition = def.prefix[def.forkIndex]!.position;

    // Options are the distinct directions leaving the fork. Courses that share a
    // direction differ only further downstream, where their own fork decides.
    const optionByDirection = new Map<RailWaypoint, ForkOption>();
    for (const courseId of members) {
      const next = builds[courseId]!.waypoints[def.forkIndex + 1];
      if (!next) continue; // this course ends at the fork; not a direction
      if (optionByDirection.has(next)) continue;

      probe
        .set(
          next.position[0] - forkPosition[0],
          next.position[1] - forkPosition[1],
          next.position[2] - forkPosition[2],
        );
      optionByDirection.set(next, { courseId, lateral: probe.dot(scratchFrame.binormal) });
    }

    const optionList = [...optionByDirection.values()].sort((a, b) => a.courseId - b.courseId);
    // A single option is not a decision — nothing to select between.
    if (optionList.length < 2) continue;

    forks.push({
      key: def.key,
      commitS,
      forkWaypointIndex: def.forkIndex,
      options: optionList,
      selector: spec.selectors?.[def.key] ?? PARTY_LATERAL,
    });
  }

  const forksByCourse: Fork[][] = builds.map((build) =>
    forks
      .filter((fork) => startsWith(build, forkDefs.get(fork.key)!.prefix))
      .sort((a, b) => a.commitS - b.commitS),
  );

  return {
    courses,
    courseCount: courses.length,
    box,
    forksOn(courseId) {
      const list = forksByCourse[courseId];
      if (!list) throw new RangeError(`forksOn: course ${courseId} out of range`);
      return list;
    },
    nextForkOn(courseId, s) {
      for (const fork of this.forksOn(courseId)) if (fork.commitS >= s) return fork;
      return null;
    },
  };
}

