// Composition root.
//
// Wires the four layers together and owns the frame loop. Everything below is
// arrangement — no gameplay decision is made in this file, and no rendering
// decision either. That is what makes it short.
//
// The round-trip through `LocalTransport` looks pointless in single-player, and that
// is the point: it is the same code path a remote player's input will take. If
// single-player skipped it, the two would drift apart and multiplayer would become a
// rewrite rather than an addition.

import { FixedStepClock } from "@core/loop.js";
import {
  decodeInputFrames,
  encodeInputFrames,
  makeInputFrame,
  type InputFrame,
} from "@core/input.js";
import { Quat, Vec3 } from "@core/math/index.js";
import { HOST_PEER, LocalTransport } from "@net/transport.js";
import { Button } from "@sim/buttons.js";
import { readFlight, createFlightState } from "@sim/flight.js";
import { buildRailNetwork, type MutableRailFrame } from "@sim/rail.js";
import { MAX_PLAYERS, SimWorld } from "@sim/world.js";
import { stepSim, type TickInputs } from "@sim/step.js";
import type { SimEvent } from "@sim/events.js";
import { LEAD_DIST, SPAWN_MIN_DIST, SPAWN_VIEW_CONE } from "@content/tuning/flight.js";
import { DEMO_LEVEL } from "@content/levels/demo.js";
import { createView, type View } from "@view/index.js";

/** Keyboard bindings. Becomes user-remappable content in M3. */
const AXIS_KEYS = {
  left: ["ArrowLeft", "KeyA"],
  right: ["ArrowRight", "KeyD"],
  up: ["ArrowUp", "KeyW"],
  down: ["ArrowDown", "KeyS"],
} as const;

const BUTTON_KEYS: ReadonlyArray<readonly [readonly string[], number]> = [
  [["Space", "ShiftLeft", "ShiftRight"], Button.Fire],
  [["KeyE"], Button.Boost],
  [["KeyQ"], Button.Brake],
  [["KeyV"], Button.ViewToggle],
  [["KeyF"], Button.AimMode],
];

class Keyboard {
  private readonly down = new Set<string>();
  // Keys that went down since the last `sample`, whether or not they are still held.
  // Without this a tap shorter than a frame is invisible: the sim only samples when a
  // tick runs, so a keydown/keyup pair landing between two frames is never observed —
  // and every edge-triggered button (view toggle, aim mode) silently misses it. The
  // latch guarantees each keydown is seen by at least one tick.
  private readonly tapped = new Set<string>();

  attach(target: Window): () => void {
    const onDown = (e: KeyboardEvent) => {
      this.down.add(e.code);
      this.tapped.add(e.code);
      // Arrow keys and space scroll the page otherwise, which is disorienting mid-run.
      if (e.code.startsWith("Arrow") || e.code === "Space") e.preventDefault();
    };
    const onUp = (e: KeyboardEvent) => this.down.delete(e.code);
    // A tab switch drops keyup, leaving the ship flying with the stick pinned. The
    // latch is not cleared here: a tap immediately before losing focus still happened.
    const onBlur = () => this.down.clear();

    target.addEventListener("keydown", onDown);
    target.addEventListener("keyup", onUp);
    target.addEventListener("blur", onBlur);
    return () => {
      target.removeEventListener("keydown", onDown);
      target.removeEventListener("keyup", onUp);
      target.removeEventListener("blur", onBlur);
    };
  }

  private any(codes: readonly string[]): boolean {
    return codes.some((code) => this.down.has(code) || this.tapped.has(code));
  }

  sample(tick: number): InputFrame {
    const steerX = (this.any(AXIS_KEYS.right) ? 1 : 0) - (this.any(AXIS_KEYS.left) ? 1 : 0);
    const steerY = (this.any(AXIS_KEYS.up) ? 1 : 0) - (this.any(AXIS_KEYS.down) ? 1 : 0);
    let buttons = 0;
    for (const [codes, bit] of BUTTON_KEYS) if (this.any(codes)) buttons |= bit;
    // Cleared only after the frame is built, so exactly one tick sees each tap. Held
    // keys keep reporting through `down`; released ones stop here, which is what makes
    // the next tick's edge detection see a falling edge and re-arm the toggle.
    this.tapped.clear();
    return makeInputFrame(tick, steerX, steerY, buttons);
  }
}

/** Builds a world seeded with the demo level and one ship on the rail. */
function createRun(seed: number): SimWorld {
  const world = new SimWorld({ seed });
  world.rail = buildRailNetwork(DEMO_LEVEL.rail);
  world.railSpeed = DEMO_LEVEL.speed;
  world.spawnConfig = {
    leadDistance: LEAD_DIST,
    minDistance: SPAWN_MIN_DIST,
    viewConeAngle: SPAWN_VIEW_CONE,
    spread: DEMO_LEVEL.spawnSpread,
    maxAlive: DEMO_LEVEL.maxAlive,
    ratePerSecond: DEMO_LEVEL.spawnRate,
  };

  const frame: MutableRailFrame = {
    position: new Vec3(),
    tangent: new Vec3(),
    normal: new Vec3(),
    binormal: new Vec3(),
  };
  world.rail.courses[0]!.frameAt(0, frame);
  const facing = new Quat().setFromBasis(
    frame.tangent,
    frame.normal,
    new Vec3().crossVectors(frame.tangent, frame.normal).normalize(),
  );
  world.spawnShip(0, frame.position.clone(), facing);
  return world;
}

export interface GameHandle {
  readonly world: SimWorld;
  readonly clock: FixedStepClock;
  readonly view: View;
  stop(): void;
  restart(): void;
  readonly recentEvents: readonly SimEvent[];
}

export function startGame(canvas: HTMLCanvasElement, seed = 1): GameHandle {
  const clock = new FixedStepClock({ hz: 60 });
  const transport = new LocalTransport();
  const keyboard = new Keyboard();
  const detachKeyboard = keyboard.attach(window);
  const view = createView(canvas);

  let world = createRun(seed);
  const inputs: (InputFrame | undefined)[] = new Array(MAX_PLAYERS).fill(undefined);
  let recentEvents: SimEvent[] = [];
  let running = true;
  let previous = 0;
  let raf = 0;

  const resize = () => view.resize(window.innerWidth, window.innerHeight);
  resize();
  window.addEventListener("resize", resize);

  const frame = (now: number) => {
    if (!running) return;
    raf = requestAnimationFrame(frame);

    const deltaSeconds = previous === 0 ? 0 : (now - previous) / 1000;
    previous = now;

    for (let step = 0, steps = clock.advance(deltaSeconds); step < steps; step++) {
      // Sample -> encode -> send -> receive -> decode -> apply. In multiplayer the
      // middle of that chain becomes a data channel; nothing on either end changes.
      transport.send(HOST_PEER, encodeInputFrames([keyboard.sample(world.tick)]), "unreliable");

      inputs.fill(undefined);
      for (const message of transport.receive()) {
        for (const decoded of decodeInputFrames(message.data)) {
          inputs[slotForPeer(message.from)] = decoded;
        }
      }

      // Capture BEFORE stepping, inside the loop: "previous" must mean one tick back
      // even when several ticks run between two rendered frames.
      view.interpolator.capture(world);
      stepSim(world, inputs as TickInputs);
    }

    const drained = world.events.drain();
    if (drained.length > 0) recentEvents = recentEvents.concat(drained).slice(-256);

    view.render(world, clock.alpha);
  };

  raf = requestAnimationFrame(frame);

  return {
    get world() {
      return world;
    },
    clock,
    view,
    get recentEvents() {
      return recentEvents;
    },
    restart() {
      world = createRun(seed);
      recentEvents = [];
      clock.reset();
    },
    stop() {
      running = false;
      cancelAnimationFrame(raf);
      detachKeyboard();
      window.removeEventListener("resize", resize);
      transport.close();
      view.dispose();
    },
  };
}

/** Peer-to-slot mapping. Trivial today; the lobby owns it from M5. */
const slotForPeer = (peer: number): number => peer;

// ── Debug surface ─────────────────────────────────────────────────────────────
// The previous game exposed an ad-hoc `window.__sunWeasel` that the Playwright
// smokes reached into, and it grew whatever each test happened to need. This one is
// declared as a type up front, so the smoke contract is explicit and typechecked.

export interface DebugSurface {
  readonly game: GameHandle;
  fingerprint(): string;
  tick(): number;
  entityCount(): number;
  outcome(): string;
  shipPosition(slot: number): [number, number, number] | null;
  cameraPosition(): [number, number, number];
  viewMode(slot: number): string | null;
  aliveHazards(): number;
  /** Draw calls in the last rendered frame — proof the renderer is actually drawing. */
  drawCalls(): number;
  reticleVisible(): boolean;
  reticlePosition(): [number, number, number] | null;
  /** World point to viewport pixels, mirroring the old `__sunWeaselApp.project`. */
  project(point: [number, number, number]): [number, number, number];
}

declare global {
  interface Window {
    __sw?: DebugSurface;
  }
}

if (typeof window !== "undefined") {
  const canvas = document.getElementById("game") as HTMLCanvasElement | null;
  if (!canvas) throw new Error('no <canvas id="game"> on the page');

  const game = startGame(canvas);
  const scratch = new Vec3();
  const flight = createFlightState();

  window.__sw = {
    game,
    fingerprint: () => game.world.fingerprint(),
    tick: () => game.world.tick,
    entityCount: () => game.world.ecs.entityCount,
    outcome: () => game.world.outcome,
    aliveHazards: () => game.world.components.hazard.count,

    shipPosition: (slot) => {
      const entity = game.world.shipBySlot[slot];
      if (entity === undefined || !game.world.readPosition(entity, scratch)) return null;
      return scratch.toArray();
    },

    cameraPosition: () => {
      const p = game.view.camera.position;
      return [p.x, p.y, p.z];
    },

    viewMode: (slot) => {
      const entity = game.world.shipBySlot[slot];
      if (entity === undefined || !readFlight(game.world, entity, flight)) return null;
      return flight.viewMode;
    },

    drawCalls: () => game.view.renderer.info.render.calls,
    reticleVisible: () => game.view.reticle.mesh.visible,
    reticlePosition: () => {
      const p = game.view.reticle.mesh.position;
      return [p.x, p.y, p.z];
    },

    project: ([x, y, z]) => game.view.project(scratch.set(x, y, z)),
  };

  console.info(`[sun-weasel] booted at ${game.clock.hz} Hz — window.__sw is available`);
}
