// Hazard placement — the no-pop-in rule, made deterministic.
//
// The old `createOffCamSpawner` (`pewpew/sunweasel/rail/spawn.js`) had two properties
// that cannot survive into this architecture:
//
//   1. It tested candidate points against the live Three.js camera FRUSTUM. `sim` has
//      no camera and must not have one.
//   2. It REJECTION-SAMPLED, looping up to eight times and breaking early. That
//      consumes a variable number of RNG draws, which desyncs every multiplayer
//      client and makes replays irreproducible. This is a latent determinism bug in
//      the current design, not merely a porting inconvenience.
//
// The replacement keeps the player-visible guarantee — nothing appears out of thin
// air in front of you — and drops the frustum. A candidate is a pop-in if it is both
// closer than `minDistance` and inside a cone of half-angle `viewConeAngle` around
// the view direction. A cone is a conservative approximation of a frustum: it
// excludes slightly more than necessary, which is the right way to be wrong here.
//
// Crucially, placement draws a FIXED number of RNG values and corrects a bad
// candidate analytically (push it out along the view ray) instead of resampling. The
// spec asserts that draw count directly, because "it happens to be deterministic
// today" is not a property that survives a year of edits.

import { clamp, EPSILON, Vec3 } from "@core/math/index.js";
import type { Rng } from "@core/rng.js";

export interface SpawnConfig {
  /** How far ahead along the rail to seed new hazards. */
  readonly leadDistance: number;
  /** Closer than this AND inside the view cone counts as a pop-in. */
  readonly minDistance: number;
  /** Half-angle of the excluded cone around the view direction, radians. */
  readonly viewConeAngle: number;
  /** Scatter radius around the lead point. */
  readonly spread: number;
  readonly maxAlive: number;
  /** Ambient spawn rate. Accrued per tick, never per wall-clock second. */
  readonly ratePerSecond: number;
}

/** Where the player is looking, for the pop-in test. No camera involved. */
export interface SpawnViewer {
  readonly position: Vec3;
  /** Unit view direction. */
  readonly direction: Vec3;
}

/**
 * RNG draws consumed by exactly one `chooseSpawnPoint` call.
 *
 * This is part of the module's contract, not an implementation detail: any change
 * here shifts every subsequent random decision in the run. If placement needs more
 * entropy, take it from a `rng.fork()` stream instead of widening this.
 */
export const SPAWN_RNG_DRAWS = 3;

const scratch = new Vec3();
const offset = new Vec3();

/**
 * Chooses a spawn point scattered around `center` that is not a pop-in.
 *
 * Always consumes `SPAWN_RNG_DRAWS` draws from `rng`, whatever the geometry: two for
 * a uniform direction on the sphere, one for the distance along it. A candidate that
 * would pop in is corrected ANALYTICALLY — pushed out along the view ray to just past
 * `minDistance` — rather than resampled, because resampling is what made the old
 * spawner's draw count depend on where the rail happened to be pointing.
 */
export function chooseSpawnPoint(
  rng: Rng,
  center: Vec3,
  viewer: SpawnViewer,
  config: SpawnConfig,
  out: Vec3,
): Vec3 {
  rng.onUnitSphere(scratch); // 2 draws
  const distance = rng.range(0, config.spread); // 1 draw

  out.copy(center).addScaledVector(scratch, distance);
  if (!isPopIn(out, viewer, config)) return out;

  // Too close AND inside the view cone. Push it straight out from the viewer along
  // the same bearing until it is far enough to fade in rather than appear.
  offset.copy(out).sub(viewer.position);
  const length = offset.length();
  if (length < EPSILON) {
    // Exactly on the viewer: no bearing to preserve, so put it out along the view.
    out.copy(viewer.position).addScaledVector(viewer.direction, config.minDistance + config.spread);
    return out;
  }
  offset.multiplyScalar((config.minDistance + config.spread) / length);
  return out.copy(viewer.position).add(offset);
}

/**
 * True if `point` would visibly appear from nothing for `viewer`.
 *
 * A pop-in needs BOTH conditions: close enough to notice, and inside the cone the
 * player can see. Something close but off to the side was never on screen to appear
 * on; something far ahead fades in with distance.
 *
 * The cone replaces the old exact camera-frustum test, which `sim` cannot perform.
 * It is deliberately conservative — a cone circumscribing the frustum excludes a
 * little more than necessary, which is the safe direction to be wrong.
 */
export function isPopIn(
  point: Vec3,
  viewer: SpawnViewer,
  config: Pick<SpawnConfig, "minDistance" | "viewConeAngle">,
): boolean {
  offset.copy(point).sub(viewer.position);
  const distance = offset.length();
  if (distance >= config.minDistance) return false;
  if (distance < EPSILON) return true; // exactly on the viewer is as bad as it gets

  const angle = Math.acos(clamp(offset.dot(viewer.direction) / distance, -1, 1));
  return angle <= config.viewConeAngle;
}
