// The simulation world — everything the game state consists of, and nothing else.
//
// If it is not reachable from a SimWorld, it is not game state: it cannot be
// snapshotted, cannot be sent to a client, and cannot be replayed. That is the test
// to apply when deciding where a piece of data belongs. Camera view mode is a good
// example of a judgement call that goes the non-obvious way — it lives in the
// simulation, because aiming is view-relative and a client predicting its own ship
// must agree with the host about which way that ship is facing.

import { EventQueue } from "@core/events.js";
import { Hasher } from "@core/hash.js";
import { Rng } from "@core/rng.js";
import { World, type Entity } from "@core/ecs.js";
import { Quat, Vec3 } from "@core/math/index.js";
import { defineComponents, type Components } from "./components.js";
import type { AimMode } from "./flight.js";
import type { RailNetwork } from "./rail.js";
import { createStopState, type StopState } from "./stops.js";
import type { SpawnConfig } from "./spawn.js";

/** A run is undecided until it is won or lost; neither is reversible. */
export type RunOutcome = "running" | "won" | "lost";
import type { SimEvent } from "./events.js";

export const MAX_PLAYERS = 6;

export interface SimConfig {
  /** Seeds every random decision in the run. Part of the replay identity. */
  seed: number;
  /** Simulation frequency. Must match the clock driving `stepSim`. */
  hz?: number;
}

export class SimWorld {
  readonly ecs: World;
  readonly rng: Rng;
  readonly events = new EventQueue<SimEvent>();
  readonly components: Components;

  readonly hz: number;
  /** Seconds per tick. Constant — this is a fixed-timestep simulation. */
  readonly dt: number;
  readonly seed: number;

  /** The simulation's only clock. */
  tick = 0;

  /** Ship entity per player slot, or NULL for an empty slot. */
  readonly shipBySlot: (Entity | undefined)[] = new Array(MAX_PLAYERS).fill(undefined);

  // ── The party's rail state ──────────────────────────────────────────────────
  // Deliberately world state rather than per-ship components: in co-op the whole
  // party rides one rail. That is what keeps the network cost at `courseId` plus
  // `railS` — five bytes for six players — instead of a position per ship.

  /** The level's rail. Null before a run starts. Immutable content, never mutated. */
  rail: RailNetwork | null = null;
  /** Which flattened course the party is on. The host decides at a fork. */
  courseId = 0;
  /** Distance travelled along that course, in world units. */
  railS = 0;
  /** Travel speed in world units per second. Run configuration, not mutable state. */
  railSpeed = 30;
  /** True while a waypoint stop parks the rail. Set by the stop system (step 4). */
  railHolding = false;
  /**
   * Aim mode forced by an active stop, overriding each player's own toggle.
   *
   * Derived from the stop state rather than being independent — so it is
   * deliberately NOT hashed; the stop state it comes from is.
   */
  forcedAimMode: AimMode | null = null;

  /** The party's waypoint-stop state. */
  readonly stop: StopState = createStopState();
  /**
   * Waypoint indices whose stop has already been satisfied, sorted.
   *
   * Kept so a cleared stop does not re-park the party on a course that revisits it.
   * Sorted rather than a Set so the fingerprint has a stable iteration order.
   */
  readonly clearedStops: number[] = [];
  /** Hazards destroyed this run. The baseline for a destroy-N stop. */
  hazardsDestroyed = 0;

  /** Ambient spawner configuration. Null disables ambient spawning entirely. */
  spawnConfig: SpawnConfig | null = null;
  /**
   * Fractional hazards owed by the ambient rate.
   *
   * Game state, not configuration — it carries between ticks and decides when the
   * next spawn lands, so it belongs in the fingerprint.
   */
  spawnAccrual = 0;

  /** Run outcome. Once decided it never changes, and the rail stops advancing. */
  outcome: RunOutcome = "running";

  constructor({ seed, hz = 60 }: SimConfig) {
    this.seed = seed >>> 0;
    this.hz = hz;
    this.dt = 1 / hz;
    this.rng = new Rng(this.seed);
    this.ecs = new World();
    this.components = defineComponents(this.ecs);
  }

  /**
   * A hash of the complete simulation state.
   *
   * Two uses, both central to the architecture. Golden-replay tests assert this
   * against a recorded value, so an accidental gameplay change surfaces as a diff
   * rather than as a bug report months later. And in multiplayer, host and client
   * compare fingerprints to detect a desync at the tick it happens instead of when
   * it becomes visible.
   *
   * Only live rows are hashed — component columns carry spare capacity, and folding
   * in uninitialised tail slots would make the fingerprint depend on allocation
   * history rather than on game state.
   */
  fingerprint(): string {
    const hasher = new Hasher();
    hasher.u32(this.tick);
    hasher.bytes(this.rng.saveState());
    // The party's rail state is game state, so it belongs in the fingerprint.
    // `railSpeed` does not — it is run configuration, fixed for the run's lifetime.
    hasher.u32(this.courseId).f64(this.railS).u32(this.railHolding ? 1 : 0);
    hasher
      .u32(this.stop.active ? 1 : 0)
      .i32(this.stop.waypoint)
      .u32(this.stop.elapsedTicks)
      .u32(this.stop.killBaseline)
      .u32(this.stop.damaged ? 1 : 0)
      .u32(this.hazardsDestroyed)
      .u32(this.clearedStops.length)
      .f64(this.spawnAccrual)
      .u32(this.outcome === "running" ? 0 : this.outcome === "won" ? 1 : 2);
    for (const waypoint of this.clearedStops) hasher.u32(waypoint);

    for (const store of this.ecs.componentStores) {
      hasher.string(store.name).u32(store.count);
      hasher.slice(store.dense, store.count);
      for (const [, column, arity] of store.columnEntries()) {
        hasher.slice(column, store.count * arity);
      }
    }

    // The entity allocator is state too, even though no component holds it. Two
    // worlds with an identical set of live entities can still disagree about which
    // handle the next spawn gets, because the free list's order depends on the order
    // things were destroyed in. Omitting this made such worlds compare EQUAL and
    // then diverge on the next spawn — silent until long after the cause.
    const allocator = this.ecs.allocatorState();
    hasher.u32(allocator.nextIndex).u32(allocator.freeList.length);
    hasher.bytes(allocator.generations);
    for (const index of allocator.freeList) hasher.u32(index);

    return hasher.hex();
  }

  // ── Entity construction ──────────────────────────────────────────────────────
  // Kept on the world rather than scattered through systems so that the set of
  // component combinations that can exist stays small and legible.

  spawnShip(slot: number, position: Vec3, orientation = new Quat()): Entity {
    const { transform, motion, ship, boxOffset, aim, viewState } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);
    orientation.writeTo(transform.columns.rot, t * 4);

    motion.add(entity);

    const s = ship.add(entity);
    ship.columns.slot[s] = slot;
    ship.columns.health[s] = 100;
    ship.columns.fireCooldown[s] = 0;

    // Flight state. `aimDir`/`headDir` are seeded to the ship's nose (local +X
    // rotated by its orientation) and `shipUp` to its wings, so a ship starts
    // pointing where it was placed rather than snapping on the first tick.
    boxOffset.add(entity);
    const a = aim.add(entity);
    const nose = orientation.rotate(new Vec3(1, 0, 0));
    const wings = orientation.rotate(new Vec3(0, 1, 0));
    nose.writeTo(aim.columns.aimDir, a * 3);
    nose.writeTo(aim.columns.headDir, a * 3);
    wings.writeTo(aim.columns.shipUp, a * 3);
    viewState.add(entity);

    this.shipBySlot[slot] = entity;
    this.events.push({ type: "shipSpawned", entity, slot, tick: this.tick });
    return entity;
  }

  spawnProjectile(
    owner: Entity,
    ownerSlot: number,
    position: Vec3,
    velocity: Vec3,
    lifetimeTicks: number,
    damage: number,
  ): Entity {
    const { transform, motion, projectile, lifetime } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);

    const m = motion.add(entity);
    velocity.writeTo(motion.columns.vel, m * 3);

    const p = projectile.add(entity);
    projectile.columns.owner[p] = owner;
    projectile.columns.ownerSlot[p] = ownerSlot;
    projectile.columns.damage[p] = damage;

    lifetime.add(entity);
    lifetime.columns.ticks[lifetime.row(entity)] = lifetimeTicks;

    this.events.push({
      type: "projectileFired",
      entity,
      firedBy: owner,
      slot: ownerSlot,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  spawnHazard(position: Vec3, radius: number, health = 1): Entity {
    const { transform, motion, hazard } = this.components;
    const entity = this.ecs.create();

    const t = transform.add(entity);
    position.writeTo(transform.columns.pos, t * 3);
    motion.add(entity); // stationary for now; drift lands with the spawner in step 5

    const h = hazard.add(entity);
    hazard.columns.radius[h] = radius;
    hazard.columns.health[h] = health;

    this.events.push({
      type: "hazardSpawned",
      entity,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    return entity;
  }

  /**
   * Destroys a hazard and credits the kill.
   *
   * The counter is what a destroy-N stop measures against its baseline, so it has to
   * be incremented here rather than by whatever caused the destruction — otherwise a
   * new damage source would silently stop counting toward stops.
   */
  destroyHazard(entity: Entity, bySlot = -1): boolean {
    if (!this.components.hazard.has(entity)) return false;

    const position = new Vec3();
    this.readPosition(entity, position);
    // Only a CREDITED kill counts toward a destroy-N stop. Ramming a rock removes it
    // (bySlot -1) but must not advance an objective that asks you to shoot things.
    if (bySlot >= 0) this.hazardsDestroyed++;
    this.events.push({
      type: "hazardDestroyed",
      entity,
      bySlot,
      x: position.x,
      y: position.y,
      z: position.z,
      tick: this.tick,
    });
    this.ecs.destroyLater(entity);
    return true;
  }

  /** Applies damage to a ship. Returns the health remaining. */
  damageShip(entity: Entity, amount: number): number {
    const { ship } = this.components;
    const s = ship.row(entity);
    if (s < 0) return 0;

    const remaining = ship.columns.health[s]! - amount;
    ship.columns.health[s] = remaining;

    // A "take damage" stop releases on the first hit during the hold. Recorded here
    // rather than inferred from the event queue, which the view drains and the sim
    // must not read back.
    if (this.stop.active) this.stop.damaged = true;

    this.events.push({
      type: "shipDamaged",
      entity,
      slot: ship.columns.slot[s]!,
      amount,
      remaining,
      tick: this.tick,
    });
    return remaining;
  }

  /** Reads an entity's position into `out`. Returns false if it has no transform. */
  readPosition(entity: Entity, out: Vec3): boolean {
    const row = this.components.transform.row(entity);
    if (row < 0) return false;
    out.readFrom(this.components.transform.columns.pos, row * 3);
    return true;
  }
}

export function createSimWorld(config: SimConfig): SimWorld {
  return new SimWorld(config);
}
