// Hazards and projectiles, drawn as instanced meshes.
//
// One draw call each rather than one per object. The old engine created a Mesh per
// asteroid and disposed it on death, which is both a draw-call per rock and steady
// GC pressure — neither survives six-player densities. Instance matrices are written
// straight from the interpolated simulation state each frame; nothing is allocated.

import {
  Color,
  DynamicDrawUsage,
  IcosahedronGeometry,
  InstancedMesh,
  Matrix4,
  MeshStandardMaterial,
  Quaternion,
  SphereGeometry,
  Vector3,
  type Scene,
} from "three";
import type { Entity } from "@core/ecs.js";
import { Vec3 } from "@core/math/index.js";
import type { SimWorld } from "@sim/world.js";
import type { TransformInterpolator } from "./interpolation.js";

/** Upper bound on simultaneously drawn instances. Excess is simply not drawn. */
const MAX_HAZARDS = 512;
const MAX_PROJECTILES = 512;

const matrix = new Matrix4();
const position = new Vector3();
const rotation = new Quaternion();
const scale = new Vector3(1, 1, 1);
const sample = new Vec3();

export interface Field {
  readonly hazards: InstancedMesh;
  readonly projectiles: InstancedMesh;
  update(world: SimWorld, interpolator: TransformInterpolator, alpha: number): void;
  dispose(): void;
}

export function createField(scene: Scene): Field {
  // Low-poly icosahedra read as rocks and cost almost nothing; real art is M2.
  const hazards = new InstancedMesh(
    new IcosahedronGeometry(1, 0),
    new MeshStandardMaterial({ color: new Color(0x8a7f72), flatShading: true, roughness: 0.9 }),
    MAX_HAZARDS,
  );
  hazards.instanceMatrix.setUsage(DynamicDrawUsage);
  hazards.frustumCulled = false; // instance matrices move every frame
  hazards.count = 0;
  scene.add(hazards);

  const projectiles = new InstancedMesh(
    new SphereGeometry(0.22, 8, 6),
    new MeshStandardMaterial({ color: new Color(0xff5a5a), emissive: new Color(0xff2020) }),
    MAX_PROJECTILES,
  );
  projectiles.instanceMatrix.setUsage(DynamicDrawUsage);
  projectiles.frustumCulled = false;
  projectiles.count = 0;
  scene.add(projectiles);

  const writeInstances = (
    mesh: InstancedMesh,
    world: SimWorld,
    entities: Uint32Array,
    count: number,
    max: number,
    interpolator: TransformInterpolator,
    alpha: number,
    radiusOf: (row: number) => number,
  ): void => {
    const drawn = Math.min(count, max);
    for (let row = 0; row < drawn; row++) {
      const entity = entities[row]! as Entity;
      interpolator.position(world, entity, alpha, sample);
      position.set(sample.x, sample.y, sample.z);
      const r = radiusOf(row);
      scale.set(r, r, r);
      matrix.compose(position, rotation, scale);
      mesh.setMatrixAt(row, matrix);
    }
    mesh.count = drawn;
    mesh.instanceMatrix.needsUpdate = true;
  };

  return {
    hazards,
    projectiles,

    update(world, interpolator, alpha) {
      const hazardStore = world.components.hazard;
      writeInstances(
        hazards,
        world,
        hazardStore.dense,
        hazardStore.count,
        MAX_HAZARDS,
        interpolator,
        alpha,
        (row) => hazardStore.columns.radius[row]!,
      );

      const projectileStore = world.components.projectile;
      writeInstances(
        projectiles,
        world,
        projectileStore.dense,
        projectileStore.count,
        MAX_PROJECTILES,
        interpolator,
        alpha,
        () => 1,
      );
    },

    dispose() {
      hazards.geometry.dispose();
      (hazards.material as MeshStandardMaterial).dispose();
      projectiles.geometry.dispose();
      (projectiles.material as MeshStandardMaterial).dispose();
    },
  };
}
