// Component definitions.
//
// Registration order is part of the wire format and part of the replay
// fingerprint (see `core/ecs`), so components are declared HERE, in one place, all
// at once, and never conditionally. Adding a component at the end is safe; inserting
// one in the middle changes every fingerprint and every snapshot layout.
//
// Field types are chosen for the wire as much as for the maths: f32 for anything
// spatial (half the bytes of f64 and well beyond the precision a rail shooter's
// world extents need), integers everywhere a value is naturally discrete. Durations
// are stored in TICKS, never in milliseconds — the simulation has no wall clock.

import type { World } from "@core/ecs.js";

export const TransformSchema = {
  /** World position. */
  pos: ["f32", 3],
  /** Orientation as a unit quaternion (x, y, z, w). */
  rot: ["f32", 4],
} as const;

export const MotionSchema = {
  /** Linear velocity, world units per second. */
  vel: ["f32", 3],
} as const;

export const ShipSchema = {
  /** Player slot, 0..5. Also the index into the per-tick input array. */
  slot: "u8",
  /** Current hull. Signed so overkill damage is representable before clamping. */
  health: "i16",
  /** Ticks remaining before this ship may fire again. */
  fireCooldown: "u16",
} as const;

export const ProjectileSchema = {
  /** The ship that fired this shot, as a packed entity handle. */
  owner: "u32",
  /** Player slot of the owner, carried so scoring survives the owner's death. */
  ownerSlot: "u8",
  damage: "u16",
} as const;

export const LifetimeSchema = {
  /** Ticks remaining. Reaching zero destroys the entity. */
  ticks: "u16",
} as const;

/** An asteroid or other destructible obstacle. */
export const HazardSchema = {
  /** Collision radius. */
  radius: "f32",
  health: "i16",
} as const;

/** A ship's offset from the rail centre, within the travel box. */
export const BoxOffsetSchema = {
  /** Along the box width axis (the rail frame's binormal). */
  ox: "f32",
  /** Along the box height axis (the rail frame's normal). */
  oy: "f32",
} as const;

/**
 * The aircraft-style aim state, as unit direction vectors.
 *
 * Kept as vectors rather than quaternions to match `FLIGHT_AND_AIM.md`, which is the
 * specification for this model — the reticle-leads/heading-lags relationship is
 * stated there in terms of two directions and the angle between them, and the ship's
 * orientation quaternion is derived from them rather than being the source of truth.
 */
export const AimSchema = {
  /** Where the shot goes. Responds immediately to input. */
  aimDir: ["f32", 3],
  /** Where the nose points. Eases toward `aimDir`. */
  headDir: ["f32", 3],
  /**
   * The ship's up-vector, PARALLEL-TRANSPORTED across each heading change rather
   * than rebuilt from world-up. Rebuilding degenerates and flips when the heading
   * points straight up or down; transport is continuous by construction. This is
   * also the camera's up, so a flip here would be visible as a view roll.
   */
  shipUp: ["f32", 3],
} as const;

/** Per-ship view and aim mode. Simulation state, not renderer state — see world.ts. */
export const ViewStateSchema = {
  /** 0 = free, 1 = forward, 2 = omni. Mirrors `AimMode` in flight.ts. */
  aimMode: "u8",
  /** 0 = cockpit, 1 = third-person. Mirrors `ViewMode` in flight.ts. */
  viewMode: "u8",
  /**
   * Last tick's button bitfield, for rising-edge detection.
   *
   * Edges have to be derived from state rather than from "the previous input
   * frame", because a client rewinding for prediction re-simulates ticks whose
   * predecessors are no longer to hand.
   */
  lastButtons: "u16",
} as const;

export type Components = ReturnType<typeof defineComponents>;

/**
 * Registers every component on a world and returns the stores.
 *
 * Called exactly once per world, from `createSimWorld`. The returned object is the
 * only handle systems get — there is deliberately no global registry, so a test can
 * stand up several independent worlds (which is precisely what the host-versus-client
 * convergence tests need).
 */
export function defineComponents(ecs: World) {
  return {
    transform: ecs.defineComponent("transform", TransformSchema, 256),
    motion: ecs.defineComponent("motion", MotionSchema, 256),
    ship: ecs.defineComponent("ship", ShipSchema, 8),
    projectile: ecs.defineComponent("projectile", ProjectileSchema, 256),
    lifetime: ecs.defineComponent("lifetime", LifetimeSchema, 256),
    // Appended in M1a step 3. Adding at the END is safe; inserting in the middle
    // would change every fingerprint and every snapshot layout.
    boxOffset: ecs.defineComponent("boxOffset", BoxOffsetSchema, 8),
    aim: ecs.defineComponent("aim", AimSchema, 8),
    viewState: ecs.defineComponent("viewState", ViewStateSchema, 8),
    // Appended in M1a step 4.
    hazard: ecs.defineComponent("hazard", HazardSchema, 128),
  };
}
