// The ambient hazard spawner.
//
// Seeds the field ahead of the party as they travel. Two properties matter more than
// the placement itself:
//
//   1. The rate accrues from TICKS, never from a wall clock. The old spawner
//      multiplied a per-second rate by a variable frame delta, so a player on a
//      slower machine met a different number of asteroids.
//   2. Each placement consumes a FIXED number of RNG draws (see `chooseSpawnPoint`),
//      so a run is reproducible and six clients agree.

import { Vec3 } from "@core/math/index.js";
import { chooseSpawnPoint, type SpawnViewer } from "../spawn.js";
import type { SimWorld } from "../world.js";

const HAZARD_RADIUS = 1.5;

const center = new Vec3();
const spawnAt = new Vec3();
const viewerPosition = new Vec3();
const viewerDirection = new Vec3();

export function spawnSystem(world: SimWorld): void {
  const config = world.spawnConfig;
  const rail = world.rail;
  if (!config || !rail) return;

  // Ambient spawning pauses during a stop. The stop's own burst is the authored
  // content there, and an omni stop lets ships face any direction — which would make
  // a single representative viewer (below) the wrong approximation.
  if (world.railHolding) return;

  const course = rail.courses[world.courseId];
  if (!course) return;

  world.spawnAccrual += config.ratePerSecond * world.dt;

  const hazard = world.components.hazard;
  while (world.spawnAccrual >= 1) {
    world.spawnAccrual -= 1;
    if (hazard.count >= config.maxAlive) continue;

    // Seed ahead along the rail, so hazards approach rather than materialise beside
    // the party. Clamped to the rail's end near the finish.
    const lead = Math.min(course.length, world.railS + config.leadDistance);
    course.sample(lead, center);

    // One representative viewer for the whole party: the rail centre, looking
    // down-track. Every ship rides the travel box around that point — a few units
    // off at most — and the cone test is deliberately conservative, so a placement
    // safe for the centre is safe for all six. Approximating here rather than
    // testing six viewers keeps the draw count fixed, which is the property that
    // actually matters for determinism.
    course.sample(world.railS, viewerPosition);
    course.tangentAt(world.railS, viewerDirection);
    const viewer: SpawnViewer = { position: viewerPosition, direction: viewerDirection };

    chooseSpawnPoint(world.rng, center, viewer, config, spawnAt);
    world.spawnHazard(spawnAt, HAZARD_RADIUS);
  }
}
