// The M1 demo level.
//
// Authored in TypeScript rather than JSON deliberately: the content SCHEMAS and their
// validators are M2 work, and inventing a half-schema now would mean migrating it
// twice. This is one hand-written level whose only job is to have something to fly
// while the vertical slice is judged by hand.
//
// It is shaped to exercise the things worth looking at: a long sweeping curve (the
// rail-curvature carry), a climb and descent (the rotation-minimizing frame away from
// world-up), and two waypoint stops — one that forces the tight forward cone, one omni
// stop where the pole can actually be crossed.

import type { RailSpec } from "../schemas/level.js";

export interface DemoLevel {
  readonly name: string;
  readonly rail: RailSpec;
  /** World units per second along the rail. */
  readonly speed: number;
  readonly spawnRate: number;
  readonly spawnSpread: number;
  readonly maxAlive: number;
}

export const DEMO_LEVEL: DemoLevel = {
  name: "Shakedown",
  speed: 34,
  spawnRate: 3.5,
  spawnSpread: 16,
  maxAlive: 60,

  rail: {
    box: { width: 8, height: 5 },
    waypoints: [
      { position: [0, 0, 0] },
      { position: [80, 0, 0] },
      // A sweeping right-hand curve — hands-off should track it, not lag it.
      { position: [160, 6, 40] },
      { position: [240, 10, 20] },
      // Destroy-two stop: forces the tight forward cone and spawns its own targets.
      {
        position: [300, 10, -20],
        stop: { mode: "forward", advance: { type: "destroyed", count: 2 }, burst: 5 },
      },
      { position: [370, 24, -60] },
      // A climb, well away from world-up, where a naive frame would degenerate.
      { position: [420, 60, -80] },
      // Omni stop: the full sphere, so the pole is reachable by pitching up.
      {
        position: [450, 90, -80],
        stop: { mode: "omni", advance: { type: "time", seconds: 6 } },
      },
      { position: [500, 110, -40] },
      { position: [560, 100, 20] },
      { position: [640, 80, 40] },
    ],
  },
};
