// Seeded pseudo-random number generator.
//
// `Math.random` is banned inside `sim` (see eslint.config.js) because an unseeded
// source makes replays, prediction, and rollback impossible. This is the only
// randomness the simulation gets, and its state is part of the world snapshot — so
// a client that reconciles to a host snapshot also reconciles its random stream.
//
// Algorithm: sfc32, seeded through splitmix32. Both are pure uint32 arithmetic
// (`Math.imul`, shifts, `>>> 0`), which JS specifies exactly — unlike the floating
// point in `core/math`, this IS bit-identical across engines.

const SEED_WORDS = 4;

/** splitmix32 — expands one 32-bit seed into a well-distributed stream. */
function splitmix32(state: number): () => number {
  let s = state >>> 0;
  return () => {
    s = (s + 0x9e3779b9) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 16), 0x21f0aaad) >>> 0;
    t = Math.imul(t ^ (t >>> 15), 0x735a2d97) >>> 0;
    return (t ^ (t >>> 15)) >>> 0;
  };
}

export class Rng {
  private a = 0;
  private b = 0;
  private c = 0;
  private d = 0;

  constructor(seed = 0) {
    this.reseed(seed);
  }

  reseed(seed: number): this {
    const mix = splitmix32(seed);
    this.a = mix();
    this.b = mix();
    this.c = mix();
    this.d = mix();
    // Discard the first few outputs so low-entropy seeds (0, 1, 2 …) diverge
    // immediately rather than sharing a correlated prefix.
    for (let i = 0; i < 12; i++) this.uint32();
    return this;
  }

  /** The core step: a uniform 32-bit unsigned integer. */
  uint32(): number {
    let { a, b, c, d } = this;
    const t0 = (a + b) | 0;
    a = b ^ (b >>> 9);
    b = (c + (c << 3)) | 0;
    c = (c << 21) | (c >>> 11);
    d = (d + 1) | 0;
    const t = (t0 + d) | 0;
    c = (c + t) | 0;
    this.a = a >>> 0;
    this.b = b >>> 0;
    this.c = c >>> 0;
    this.d = d >>> 0;
    return t >>> 0;
  }

  /** Uniform float in [0, 1). */
  float(): number {
    return this.uint32() / 4294967296;
  }

  /** Uniform float in [min, max). */
  range(min: number, max: number): number {
    return min + this.float() * (max - min);
  }

  /** Uniform integer in [min, max). Returns `min` if the range is empty. */
  int(min: number, max: number): number {
    const span = Math.max(0, Math.floor(max) - Math.floor(min));
    return span === 0 ? Math.floor(min) : Math.floor(min) + (this.uint32() % span);
  }

  /** True with probability `p`. */
  bool(p = 0.5): boolean {
    return this.float() < p;
  }

  /** Uniform sign, -1 or +1. */
  sign(): number {
    return this.uint32() & 1 ? 1 : -1;
  }

  /** A uniformly distributed element, or `undefined` for an empty array. */
  pick<T>(items: readonly T[]): T | undefined {
    return items.length === 0 ? undefined : items[this.int(0, items.length)];
  }

  /**
   * Fisher-Yates, in place. Deterministic given the stream position — but note it
   * consumes a variable number of draws, so two code paths that shuffle
   * conditionally will desync each other. Prefer `fork()` for anything optional.
   */
  shuffle<T>(items: T[]): T[] {
    for (let i = items.length - 1; i > 0; i--) {
      const j = this.int(0, i + 1);
      const tmp = items[i]!;
      items[i] = items[j]!;
      items[j] = tmp;
    }
    return items;
  }

  /**
   * Writes a uniformly distributed point on the unit sphere into `out`.
   * Uses the cylindrical-projection method: exactly two draws, no rejection loop,
   * so the number of draws consumed is constant — which matters for determinism.
   */
  onUnitSphere(out: { x: number; y: number; z: number }): void {
    const z = this.range(-1, 1);
    const theta = this.range(0, Math.PI * 2);
    const r = Math.sqrt(Math.max(0, 1 - z * z));
    out.x = r * Math.cos(theta);
    out.y = r * Math.sin(theta);
    out.z = z;
  }

  /**
   * A child generator derived deterministically from this one's CURRENT state plus
   * a stream id. Use this to give a subsystem (a wave, a debris burst) its own
   * stream, so that changing how many draws it makes cannot shift every other
   * subsystem's stream — the classic source of "one tweak reshuffled the level".
   */
  fork(streamId: number): Rng {
    const mixed = (Math.imul(this.uint32() ^ streamId, 0x45d9f3b) ^ (streamId << 16)) >>> 0;
    return new Rng(mixed);
  }

  // ── Snapshot interop ────────────────────────────────────────────────────────

  saveState(out = new Uint32Array(SEED_WORDS)): Uint32Array {
    out[0] = this.a;
    out[1] = this.b;
    out[2] = this.c;
    out[3] = this.d;
    return out;
  }

  loadState(state: ArrayLike<number>): this {
    this.a = (state[0] ?? 0) >>> 0;
    this.b = (state[1] ?? 0) >>> 0;
    this.c = (state[2] ?? 0) >>> 0;
    this.d = (state[3] ?? 0) >>> 0;
    return this;
  }

  clone(): Rng {
    return new Rng(0).loadState(this.saveState());
  }
}

export const RNG_STATE_WORDS = SEED_WORDS;

/** Turns a human-readable seed ("orbital-scrapyard") into a 32-bit seed. */
export function seedFromString(s: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}
